function isValidId(k){ return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(k); }
function propKey(k){ return isValidId(k) ? k : JSON.stringify(k); }
function singular(s){ s=String(s==null?'Item':s); var r=s.replace(/s$/,''); return r||'Item'; }
function pascalCase(s){
  s=String(s==null?'':s).replace(/[^A-Za-z0-9]+/g,' ').trim();
  if(!s) return 'Root';
  return s.split(/\s+/).map(function(w){ return w.charAt(0).toUpperCase()+w.slice(1); }).join('');
}
function parseSafe(s){ try{ return {ok:true, value:JSON.parse(s)}; } catch(e){ return {ok:false, error:e.message}; } }
function inferType(v){
  if(v===null) return 'null';
  if(Array.isArray(v)) return 'array';
  var t=typeof v;
  if(t==='object') return 'object';
  return t;
}
function jsonToInterfaces(root, rootName){
  var out=[]; var names={};
  function uniqueName(base){ base=pascalCase(base); var n=base,i=2; while(names[n]){ n=base+(i++); } names[n]=1; return n; }
  function typeOf(v, keyHint){
    if(v===null) return 'null';
    if(Array.isArray(v)){
      if(!v.length) return 'any[]';
      var set={}, order=[];
      for(var i=0;i<v.length;i++){ var tt=typeOf(v[i], singular(keyHint)); if(!set[tt]){ set[tt]=1; order.push(tt); } }
      var inner = order.length===1 ? order[0] : ('('+order.join(' | ')+')');
      return inner+'[]';
    }
    var t=typeof v;
    if(t==='object') return emit(v, keyHint);
    if(t==='number'||t==='string'||t==='boolean') return t;
    return 'any';
  }
  function emit(obj, keyHint){
    var name=uniqueName(keyHint||'Object');
    var lines=['export interface '+name+' {'];
    var keys=Object.keys(obj);
    for(var i=0;i<keys.length;i++){ lines.push('  '+propKey(keys[i])+': '+typeOf(obj[keys[i]], keys[i])+';'); }
    lines.push('}');
    out.push(lines.join('\n'));
    return name;
  }
  rootName = rootName || 'Root';
  if(Array.isArray(root)){
    out.push('export type '+pascalCase(rootName)+' = '+typeOf(root, rootName)+';');
  } else if(root!==null && typeof root==='object'){
    emit(root, rootName);
  } else {
    out.push('export type '+pascalCase(rootName)+' = '+typeOf(root, rootName)+';');
  }
  return out.join('\n\n');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { jsonToInterfaces:jsonToInterfaces, inferType:inferType, parseSafe:parseSafe, pascalCase:pascalCase, propKey:propKey, singular:singular };
}
